SET ROLE postgres;

BEGIN;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'institutions_country_name_unique'
                  AND conrelid = 'public.institutions'::regclass) THEN
    RAISE EXCEPTION 'REFUSING: 20261095 (institutions.country, per-country names) is not applied. Nothing applied.';
  END IF;
END $$;

-- A name already used in CY by a DIFFERENT id would make the INSERT fail with a bare
-- 23505; say which instead.
DO $$
DECLARE v_clash text;
BEGIN
  SELECT string_agg(i.name, ' · ') INTO v_clash
    FROM public.institutions i
    JOIN (VALUES
      ('9eb5dba7-f562-548b-a398-3d91b75689e6'::uuid, 'University of Cyprus'),
      ('c4f2c066-835d-52db-abea-d4e36ca92ee0'::uuid, 'Cyprus University of Technology'),
      ('da2a3802-96f5-5c0d-9223-407dfc4ea08b'::uuid, 'Open University of Cyprus'),
      ('1c406120-7285-5435-b8b4-b8309e090ddc'::uuid, 'Frederick University'),
      ('85d48338-e785-53e8-bc2a-b4e6da794b3d'::uuid, 'European University Cyprus'),
      ('c0851764-71bf-5d21-b037-14ff0139dc19'::uuid, 'University of Nicosia'),
      ('1dbc5b70-15f8-50a2-8270-7bcef9add0e2'::uuid, 'Neapolis University Pafos'),
      ('831848be-4da8-5ad9-8ebc-745e25f0c2cf'::uuid, 'University of Central Lancashire Cyprus'),
      ('49b18428-537e-5665-a159-483d54236bba'::uuid, 'Philips University'),
      ('7682672a-88a8-5d81-9d1f-0ecbeb83a6ae'::uuid, 'American University of Cyprus'),
      ('f6f9464f-d155-5f98-b635-08252fbd3422'::uuid, 'University of Limassol'),
      ('850866ed-c2f4-5833-ad50-7d2e8d5c84d9'::uuid, 'American University of Beirut – Mediterraneo')
    ) AS v(id, name) ON v.name = i.name AND i.country = 'CY' AND i.id <> v.id;
  IF v_clash IS NOT NULL THEN
    RAISE EXCEPTION 'REFUSING: already in CY under another id: %. Nothing applied.', v_clash;
  END IF;
END $$;

-- Against the TRNC rows: the names this seed shares with an XN row must be EXACTLY the
-- reviewed allowance ([]). Printed either way.
DO $$
DECLARE v_shared text;
BEGIN
  SELECT coalesce(string_agg(DISTINCT i.name, ' · ' ORDER BY i.name), '') INTO v_shared
    FROM public.institutions i
    JOIN (VALUES
      ('University of Cyprus'),
      ('Cyprus University of Technology'),
      ('Open University of Cyprus'),
      ('Frederick University'),
      ('European University Cyprus'),
      ('University of Nicosia'),
      ('Neapolis University Pafos'),
      ('University of Central Lancashire Cyprus'),
      ('Philips University'),
      ('American University of Cyprus'),
      ('University of Limassol'),
      ('American University of Beirut – Mediterraneo')
    ) AS v(name) ON lower(v.name) = lower(i.name) AND i.country = 'XN';
  RAISE NOTICE 'names shared with TRNC rows: [%]', v_shared;
  IF v_shared IS DISTINCT FROM '' THEN
    RAISE EXCEPTION 'REFUSING: names shared with TRNC rows are [%], reviewed allowance is []. Nothing applied.', v_shared;
  END IF;
END $$;

