   WHERE country = 'CY' AND id IN ('9eb5dba7-f562-548b-a398-3d91b75689e6','c4f2c066-835d-52db-abea-d4e36ca92ee0','da2a3802-96f5-5c0d-9223-407dfc4ea08b','1c406120-7285-5435-b8b4-b8309e090ddc','85d48338-e785-53e8-bc2a-b4e6da794b3d','c0851764-71bf-5d21-b037-14ff0139dc19','1dbc5b70-15f8-50a2-8270-7bcef9add0e2','831848be-4da8-5ad9-8ebc-745e25f0c2cf','49b18428-537e-5665-a159-483d54236bba','7682672a-88a8-5d81-9d1f-0ecbeb83a6ae','f6f9464f-d155-5f98-b635-08252fbd3422','850866ed-c2f4-5833-ad50-7d2e8d5c84d9');
  IF v_here <> 12 THEN
